        if (expert_weights[(size_t) e].size() != expert_bytes) throw std::runtime_error(name + ": expert size mismatch");
        std::copy(expert_weights[(size_t) e].begin(), expert_weights[(size_t) e].end(),
                  w.begin() + (size_t) e * expert_bytes);
    }

