            const float* xr = x.data() + (size_t) src[r] * c.cols;
            for (int64_t o = 0; o < c.rows; ++o) {
                double acc = 0;
                const float* wr = wd.data() + (size_t) o * c.cols;
                for (int64_t k = 0; k < c.cols; ++k) acc += (double) wr[k] * xr[k];
                ref[(size_t) dst[r] * c.rows + o] = (float) acc;
            }
        }
    }
