        {GGML_TYPE_Q2_0, 1280, 2560, {16}, true, 0},       {GGML_TYPE_Q2_0, 1280, 2560, {64}, true, 0},
        {GGML_TYPE_Q2_0, 1280, 2560, {5, 130}, false, 0},  {GGML_TYPE_Q2_0, 1280, 2560, {5, 130}, false, 5},
        // other types at the test's geometry
