        {GGML_TYPE_Q2_0, 2560, 640, {1, 3, 3}, false, 0},   {GGML_TYPE_Q2_0, 2560, 640, {64}, true, 0},
        {GGML_TYPE_IQ4_NL, 2560, 640, {1, 3, 3}, false, 0}, {GGML_TYPE_Q8_0, 2560, 640, {64}, true, 0},
